    @if (_showValidation && string.IsNullOrWhiteSpace(Model.Phone))
    {
        <div class="invalid-feedback d-block">Phone number is required.</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control @ValidationClass(Model.Address)" rows="2" @bind="Model.Address"></textarea>
    @if (_showValidation && string.IsNullOrWhiteSpace(Model.Address))
    {
        <div class="invalid-feedback d-block">Address is required.</div>
    }
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@_validating">
        @if (_validating)
        {
            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            <span>Validating…</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private bool _showValidation;
    private bool _validating;
    private string? _emailError;

    private async Task HandleNext()
    {
        _showValidation = true;
        _emailError = null;

        if (!Model.IsValid()) return;

        if (ValidateEmail is not null)
        {
            _validating = true;
            StateHasChanged();

            var isValid = await ValidateEmail(Model.Email);
            _validating = false;

            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }

    private string ValidationClass(string value, string? fieldError = null)
    {
        if (!_showValidation) return "";
        if (!string.IsNullOrEmpty(fieldError)) return "is-invalid";
        return string.IsNullOrWhiteSpace(value) ? "is-invalid" : "is-valid";
    }
}
