@namespace sv_7748a9246a594afca1999cc0fdaeb700.Components.JobApplication

<nav aria-label="Application progress" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCompleted = step < CurrentStep;
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep;

            <div class="text-center flex-fill position-relative">
                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepCircleClass(step)"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@isFuture"
                        @onclick="() => OnStepClicked.InvokeAsync(step)">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @step
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : (isCurrent ? "fw-bold" : ""))">
                    @StepNames[i]
                </div>
            </div>
        }
    </div>
    <div class="progress mt-2" style="height: 4px;">
        <div class="progress-bar" role="progressbar"
             style="@($"width: {ProgressPercent}%")"
             aria-valuenow="@ProgressPercent" aria-valuemin="0" aria-valuemax="100">
        </div>
    </div>
</nav>

@code {
    private static readonly string[] StepNames =
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private int ProgressPercent => (int)((CurrentStep - 1) / (double)(StepNames.Length - 1) * 100);

    private string StepCircleClass(int step)
    {
        if (step < CurrentStep) return "btn-success text-white";
        if (step == CurrentStep) return "btn-primary text-white";
        return "btn-outline-secondary";
    }
}

