@namespace sv_7748a9246a594afca1999cc0fdaeb700.Components.JobApplication
@using sv_7748a9246a594afca1999cc0fdaeb700.Models

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryForm Entry="Entries[index]"
                   Index="index"
                   CanRemove="Entries.Count > 1"
                   OnRemove="() => RemoveEntry(index)" />
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    <span class="me-1">+</span> Add Another Position
</button>

@if (_showValidation && _validationError is not null)
{
    <div class="alert alert-danger">@_validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private bool _showValidation;
    private string? _validationError;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        _showValidation = true;
        _validationError = null;

        if (Entries.Count == 0)
        {
            _validationError = "Please add at least one work entry.";
            return;
        }

        for (int i = 0; i < Entries.Count; i++)
        {
            if (!Entries[i].IsValid())
            {
                _validationError = $"Position {i + 1} is missing required fields (company, title, or start date).";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

