@page "/apply"
@rendermode InteractiveServer
@using sv_7748a9246a594afca1999cc0fdaeb700.Components.JobApplication
@using sv_7748a9246a594afca1999cc0fdaeb700.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4 text-center">Job Application</h2>

    <StepIndicator CurrentStep="_currentStep" OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 1:
            <PersonalInfoStep Model="_personalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="() => GoToStep(2)" />
            break;

        case 2:
            <WorkHistoryStep Entries="_workEntries"
                             OnNext="() => GoToStep(3)"
                             OnBack="() => GoToStep(1)" />
            break;

        case 3:
            <ReferencesStep References="_references"
                            OnNext="() => GoToStep(4)"
                            OnBack="() => GoToStep(2)" />
            break;

        case 4:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             CoverLetterChanged="val => _coverLetter = val"
                             OnNext="() => GoToStep(5)"
                             OnBack="() => GoToStep(3)" />
            break;

        case 5:
            <ReviewStep Personal="_personalInfo"
                        WorkEntries="_workEntries"
                        References="_references"
                        CoverLetter="@_coverLetter"
                        OnBack="() => GoToStep(4)"
                        OnEditStep="GoToStep"
                        OnSubmit="SubmitApplication"
                        Submitted="_submitted"
                        ApplicationId="_applicationId" />
            break;
    }
</div>

@code {
    private int _currentStep = 1;
    private bool _submitted;
    private int _applicationId;

    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
    private readonly List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        if (step >= 1 && step <= 5 && step <= _currentStep)
        {
            _currentStep = step;
        }
        else if (step == _currentStep + 1)
        {
            _currentStep = step;
        }
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            _personalInfo.ToRecord(),
            new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
            _references.Select(r => r.ToRecord()).ToList(),
            _coverLetter
        );

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _submitted = true;
    }
}

